        var panel = new StackPanel { Orientation = Orientation.Horizontal, HorizontalAlignment = HorizontalAlignment.Left };
        var primary = new Button
        {
            Content = closeOnly ? "إغلاق" : "حفظ الخيارات",
            Width = 130,
            Height = 38,
