            Margin = new Thickness(0, 0, 8, 0),
            Padding = new Thickness(12, 6, 12, 6)
        };
        primary.Click += (_, _) =>
        {
            if (!closeOnly)
            {
                if (_paperSizeComboBox.SelectedItem is ComboBoxItem paper && paper.Tag is string paperTag)
                    SelectedPaperSize = paperTag;
                if (_columnsComboBox.SelectedItem is ComboBoxItem columns && columns.Tag is int count)
                    SelectedColumns = count;
                SelectedCutMarks = _cutMarksCheckBox.IsChecked == true;
                DialogResult = true;
            }
            else
            {
                DialogResult = false;
            }
        };
        var cancel = new Button
